package org.kanger;
import java.util.*;
import org.kanger.ContextProductionCapture.Source;
import org.kanger.ContextProductionNativeBinding.Snapshot;
import org.kanger.ContextWitnessResultTransport.*;
import org.kanger.ContextRelationalInterpretation.*;
import org.kanger.ContextSignedRelationalModelSearch.*;
final class ContextMultiOriginMatrix {
 static int checks;static final int WORK=64000000;
 static void require(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static Snapshot bind(boolean x,String s)throws Exception{return ContextRelationalModelMatrix.bind(x,s);}
 static Source source(Snapshot x){return x.primary.stream().filter(e->e.bundle!=null).findFirst().get().source;}
 static ContextSignedModelEvaluation.Result run(Snapshot x,List<Snapshot> fs){return ContextSignedModelEvaluation.runAutomatic(x,fs,new ContextSignedModelRequest("!p(1);",Collections.singletonMap("rounds",4)).policy);}
 static ContextSignedModelEvaluation.Result model(Snapshot x,List<Snapshot> fs){ContextSignedModelEvaluation.Result r=run(x,fs);require(r.status==ContextSignedModelInspection.Status.MODELLED_SUPPLIED&&r.relational!=null,r.phase+": "+r.reason);ContextSignedRelationalModelAudit.check(r.relational.output,WORK);require(true,"actual native and original/final relational receipts independently replayed");return r;}
 static List<Origin> origins(Obligation o,String name){if(o.kind==Kind.COMMON||o.kind==Kind.PRIVATE){Item i=(Item)o.carrier;if(!i.atom.predicate.equals(name))return null;List<Origin> out=new ArrayList<>();for(Slot s:i.atom.arguments)out.add(s.origin);return out;}for(org.kanger.ContextUniversalInputResiduals.Literal a:ContextSignedRelationalModelSearch.residual(o).literals)if(a.predicate.equals(name)){List<Origin> out=new ArrayList<>();for(org.kanger.ContextUniversalInputResiduals.Term t:a.arguments)out.add(t.origin);return out;}return null;}
 static void derived(ContextSignedModelEvaluation.Result r,String name,Source source,int[] pattern,int sources){boolean found=false;for(Obligation o:r.relational.output.ledger.obligations){List<Origin> args=origins(o,name);if(args==null||args.size()!=pattern.length)continue;boolean same=true;for(int n=0;n<pattern.length;n++)same&=args.get(n)!=null&&args.get(n).source.equals(source)&&args.get(n).binder==pattern[n];if(same){require(o.support.sources.size()==sources,"whole derived support for "+name);found=true;}}require(found,"actual final tuple retains exact Source/binder positions for "+name);}
 static void positive()throws Exception{
  Snapshot plain=bind(true,"!$u $v rel(u,v);");ContextSignedModelEvaluation.Result r=model(plain,Collections.emptyList());ContextRelationalInterpretation m=r.relational.output.ledger.models.get(Cut.of(plain));require(m.witnesses.size()==2&&m.witnesses.values().stream().allMatch(v->v==0),"distinct Origins inside ONE literal can denote one value; no inequality assumption");
  Snapshot asymmetric=bind(true,"!$u $v rel(u,v)&&~rel(v,u);");r=model(asymmetric,Collections.emptyList());m=r.relational.output.ledger.models.get(Cut.of(asymmetric));require(r.namedPoints==2&&new HashSet<>(m.witnesses.values()).size()==2,"ordered asymmetric tuple demands grow a genuine second value");
  Snapshot repeated=bind(true,"!$a $b $c $d wide(a,7,b,a,c,\"7\",d,b);");r=model(repeated,Collections.emptyList());m=r.relational.output.ledger.models.get(Cut.of(repeated));require(m.witnesses.size()==4&&m.points.size()==2&&m.relations.containsKey(new Signature("wide",8)),"four distinct Origins, repeated positions and typed fixed constants in one literal");
  Snapshot x=bind(true,"!$u $v rel(u,v)&&~rel(v,u);");Snapshot a=bind(false,"!@x @y rel(x,y)->swapped(y,x);"),b=bind(false,"!@x @y swapped(x,y)->done(y,x);");
  for(boolean reverse:new boolean[]{false,true}){r=model(x,reverse?Arrays.asList(b,a):Arrays.asList(a,b));derived(r,"swapped",source(x),new int[]{1,0},2);derived(r,"done",source(x),new int[]{0,1},3);require(r.branch.termination!=null,"complete all-cut continuation and termination, no seed-only success");}
  Snapshot diagonal=bind(true,"!$u $v rel(u,v);!@x ~rel(x,x);");r=model(diagonal,Collections.emptyList());m=r.relational.output.ledger.models.get(Cut.of(diagonal));require(r.namedPoints==2&&new HashSet<>(m.witnesses.values()).size()==2,"universal diagonal constraint checks aliasing without pretending Origins are unequal");
 }
 static void integrity()throws Exception{
  Snapshot x=bind(true,"!$u $v rel(u,v)&&~rel(v,u);");ContextSignedWitnessPlanAudit.Receipt p=ContextSignedWitnessFrameMatrix.plan(x,Collections.emptyList());SignedSeedFrame f=ContextSignedWitnessFrameMatrix.frame(p,x,Collections.emptyList());ContextSignedWitnessFrameAudit.Receipt receipt=ContextSignedWitnessFrameMatrix.audit(f,p,x,Collections.emptyList());Item item=f.common.items.stream().filter(i->i.atom.positive).findFirst().get();Origin first=item.atom.arguments.get(0).origin,second=item.atom.arguments.get(1).origin;
  require(first.binder==0&&second.binder==1&&first.source.equals(second.source),"one original Source has two explicit ordered Origin identities");
  ContextWitnessResultTransport.Replay replay=ContextWitnessResultTransport.restore(f.common,WORK);require(replay.witnesses.size()==2&&new HashSet<>(replay.witnesses.values()).size()==2,"native carrier restores exact two-symbol sharing bijection; model may still identify their values");
  ContextSignedWitnessFrameMatrix.mutate(item.atom.arguments.get(1),"origin",first,()->require(!ContextSignedWitnessFrameAudit.inspect(f,p,x,Collections.emptyList(),64,8,WORK,WORK).audited,"direct original audit rejects second-slot collapse"));
  List<Slot> swapped=new ArrayList<>(item.atom.arguments);Collections.reverse(swapped);ContextSignedWitnessFrameMatrix.mutate(item.atom,"arguments",Collections.unmodifiableList(swapped),()->require(!ContextSignedWitnessFrameAudit.inspect(f,p,x,Collections.emptyList(),64,8,WORK,WORK).audited,"same two Origins in wrong positions rejected"));
  ContextSignedWitnessFrameMatrix.mutate(item.atom.arguments.get(1),"value",ContextSignedUnaryModelMatrix.one(),()->require(!ContextSignedWitnessFrameAudit.inspect(f,p,x,Collections.emptyList(),64,8,WORK,WORK).audited,"Origin cannot simultaneously alias a fixed value"));
  SignedSeedResult low=ContextWitnessResultTransport.signedWitnessFrame(p,x,Collections.emptyList(),64,1,WORK,WORK);require(!low.assembled&&low.output==null,"rank counts distinct Origins inside one literal and refuses atomically");ContextSignedWitnessFrameAudit.check(receipt,p,x,Collections.emptyList(),64,8,WORK,WORK);require(true,"restored actual frame and old receipt must fresh-replay exact positions");
  Snapshot a=bind(false,"!@x @y rel(x,y)->swapped(y,x);");ContextSignedModelEvaluation.Result r=model(x,Collections.singletonList(a));Ledger good=r.relational.output.ledger;ContextRelationalInterpretation m=good.models.get(Cut.of(x));Source s=source(x);int u=m.witnesses.get(new Binder(s,0)),v=m.witnesses.get(new Binder(s,1));Map<Signature,Table> tables=new LinkedHashMap<>(m.relations);tables.put(new Signature("swapped",2),new Table(true,Collections.singletonMap(Arrays.asList(v,u),false)));ContextRelationalInterpretation wrong=new ContextRelationalInterpretation(m.points,tables,m.witnesses,m.denotations);Ledger forged=ContextMultiBinderModelMatrix.replace(good,x,wrong);
  require(ContextRelationalModelMatrix.originalAccepts(forged),"original X has no foreign swapped rule: original receipt alone can accept false final swapped tuple");require(!ContextMultiBinderModelMatrix.finalAccepts(forged),"independent ACTUAL final proof audit rejects false derived two-Origin tuple in X");
  List<Obligation> missing=new ArrayList<>(good.obligations);missing.removeIf(o->origins(o,"swapped")!=null);Ledger omitted=new Ledger(good.branch,good.policy,good.models,good.rows,missing);require(!ContextMultiBinderModelMatrix.finalAccepts(omitted),"cannot omit actual multi-Origin consequence or any Source alternative");
 }
 static void topology()throws Exception{
  Snapshot x=bind(true,"!anchor(1);"),a=bind(false,"!$u $v rel(u,v);"),b=bind(false,"!@x @y ~rel(x,y);");
  for(boolean reverse:new boolean[]{false,true}){ContextSignedModelEvaluation.Result r=model(x,reverse?Arrays.asList(b,a):Arrays.asList(a,b));ContextRelationalInterpretation ma=r.relational.output.ledger.models.get(Cut.of(a)),mb=r.relational.output.ledger.models.get(Cut.of(b));require(ma.relations.get(new Signature("rel",2)).otherwise&&!mb.relations.get(new Signature("rel",2)).otherwise,"independent positive existential/negative universal models, both connection orders");require(r.branch.termination.result.output.current().packet.items.stream().noneMatch(i->i.atom.predicate.equals("rel")),"raw foreign multi-Origin tuples never pooled into X");}
  Snapshot trusted=ContextProductionNativeBinding.trusted("multi-origin-trust",Arrays.asList(a,b),WORK);ContextSignedModelEvaluation.Result no=run(x,Collections.singletonList(trusted));require(no.status==ContextSignedModelInspection.Status.REFUTED&&no.branch!=null,"TRUST jointly refutes all physical rows, unlike independent cuts");
  Snapshot local=bind(true,"!$u $v rel(u,v);");no=run(local,Collections.singletonList(b));require(no.status==ContextSignedModelInspection.Status.REFUTED&&no.branch.initialRejection!=null,"two-Origin initial receiver refutation is independently sourced before modelling");require(no.branch.initialRejection.checks.get(Cut.of(b)).emptyProofs.stream().anyMatch(e->e.support.sources.size()==2&&e.support.sources.contains(source(local))),"empty proof retains whole local tuple Source and foreign universal Source");
 }
}
